package com.alsafa.native4;import android.app.Activity;import android.os.Bundle;import android.widget.LinearLayout;import android.widget.TextView;import com.alsafa.native4.core.CoreDb;import com.alsafa.native4.core.Native4Services;public final class ReportsActivity extends Activity{private CoreDb db;@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_reports);db=new CoreDb(this);Native4Services services=new Native4Services(db,"native4-android-alpha");ReportPanelBinder b=new ReportPanelBinder(this,services,(TextView)findViewById(R.id.status),(LinearLayout)findViewById(R.id.pageHost));b.show(true);findViewById(R.id.pageBack).setOnClickListener(v->finish());}}